// Original, transient Water Lab teaching picture. It never reads or writes a learner record.
const frames=[
 {heading:'Before cooling',image:'./cold-window-before.svg',alt:'A dry upright pane separates the air-facing side from its dry other side. No drops appear. In a separate imagined tiny view, same-size water-molecule dots are spread through invisible vapor in the air.',macro:'The pane is dry on both sides. Water vapor is already in the air, but we cannot see it.',tiny:'These same-size dots stand for a few water molecules in invisible vapor in the air. The dots are a teaching drawing, not vapor we could see.'},
 {heading:'The cooled pane',image:'./cold-window-cool.svg',alt:'Two visible liquid drops sit on the air-facing side of an unbroken cool pane; its other side stays dry. In a separate imagined tiny view, one small liquid sample contains close-together same-size molecule dots at the surface while other dots remain spread in air. No dot stands for one whole visible drop.',macro:'In this made-up air, the pane becomes cool enough for some vapor to become liquid drops on its air-facing side. This is condensation. Water did not pass through the pane.',tiny:'Some of the same-size water-molecule dots sit close together in one small liquid sample at the cool surface. Other dots remain vapor in the air. Each dot still stands for water; no dot stands for one whole visible drop.'},
 {heading:'Warm again in our model',image:'./cold-window-return.svg',alt:'The pane is dry again on both sides, with no arrow through it. In a separate imagined tiny view, the same-size water-molecule dots are spread in air as invisible vapor.',macro:'As this model pane warms, the pictured drops evaporate into invisible water vapor in the air. The other side stays dry. We did not measure when or how fast this would happen.',tiny:'The highlighted same-size dots spread back into the air as vapor. They are still water molecules; they did not grow or turn into a new substance.'}
];
const controls=[
 '<button type="button" class="primary" data-cw-action="cool">Cool the pane</button>',
 '<button type="button" class="primary" data-cw-action="warm">Let the pane warm</button><button type="button" class="secondary" data-cw-action="before">Back to before cooling</button>',
 '<button type="button" class="primary" data-cw-action="cool">Cool the pane again</button><button type="button" class="secondary" data-cw-action="before">Back to before cooling</button>'
];
const announcements={cool:'The cooled pane has drops on the air-facing side. Some invisible water vapor became liquid here: condensation.',warm:'The model drops have evaporated into invisible water vapor. This return is a model, not a timed observation.',before:'Back before cooling. The pane is dry; water vapor is still in the air.'};
function panel(phase){const f=frames[phase];return `<h2 id="window-frame-title" tabindex="-1">${f.heading}</h2><div class="cold-window-pair"><figure class="cold-window-art"><img data-cw-image src="${f.image}" alt="${f.alt}"></figure><div class="cold-window-caption"><p data-cw-macro>${f.macro}</p><p><strong>Imagined tiny view:</strong> <span data-cw-tiny>${f.tiny}</span></p></div></div>`;}
export function coldWindowPage(){return `<section class="science-view cold-window" data-cold-window-root><header class="science-heading"><a class="back" href="#science">← Water Lab</a><p class="science-eyebrow">Water Lab · original picture model</p><h1>Cold Window, Same Water</h1><p>There is invisible water vapor in the air around this made-up window. Cool the pane and compare what is on the air-facing side. The drops do not come through from the other side.</p></header><article class="cold-window-card"><div data-cw-panel>${panel(0)}</div><p data-cw-status class="cold-window-status" role="status" aria-live="polite"></p><p class="cold-window-contrast"><strong>Compare the changes:</strong> Evaporation: liquid → invisible water vapor. Condensation: water vapor → liquid drops. In both, it is still water.</p><div class="cold-window-actions" data-cw-controls>${controls[0]}</div><p data-cw-talk><strong>Talk together, if you like:</strong> Where could drops on the air-facing side come from? Tell someone or point to the part of the picture you mean. You do not need to enter an answer.</p><p><a class="cold-window-link" href="#science">Compare with the evaporation visit</a></p><details class="cold-window-sources"><summary>How this drawing works / sources</summary><p>This is an original explanatory drawing, not an observation or experiment. The dots are imagined water molecules and are not visible vapor. The two views are not to scale, and the dot count is not a measured amount. Condensation depends on the air and surface conditions; not every cooled pane will make drops. The model skips airflow, humidity thresholds, heat flow, cloud formation, and time. It shows drops on one side of an unbroken pane, not water leaking through it. There is no need for real cold glass, water, heating, or equipment.</p><ul><li><a href="https://www.usgs.gov/water-science-school/science/condensation-and-water-cycle" target="_blank" rel="noopener noreferrer">USGS: Condensation and the Water Cycle</a></li><li><a href="https://www.usgs.gov/water-science-school/science/evaporation-and-water-cycle" target="_blank" rel="noopener noreferrer">USGS: Evaporation and the Water Cycle</a></li><li><a href="https://www.noaa.gov/education/resource-collections/freshwater/water-cycle" target="_blank" rel="noopener noreferrer">NOAA: The water cycle</a></li></ul></details></article></section>`;}
export function bindColdWindow({explorerId}){
 const root=document.querySelector('[data-cold-window-root]');if(!root)return;
 const owner=explorerId();let phase=0;
 const live=()=>root.isConnected&&document.querySelector('[data-cold-window-root]')===root&&location.hash.split('/').slice(0,2).join('/')==='#science/window'&&explorerId()===owner;
 root.addEventListener('click',event=>{
  const button=event.target.closest('[data-cw-action]');if(!button||!root.contains(button)||!live())return;
  const action=button.dataset.cwAction,next=action==='before'?0:action==='cool'&&(phase===0||phase===2)?1:action==='warm'&&phase===1?2:null;
  if(next===null)return;
  phase=next;const f=frames[phase];root.querySelector('#window-frame-title').textContent=f.heading;
  const img=root.querySelector('[data-cw-image]');img.src=f.image;img.alt=f.alt;
  root.querySelector('[data-cw-macro]').textContent=f.macro;root.querySelector('[data-cw-tiny]').textContent=f.tiny;
  root.querySelector('[data-cw-controls]').innerHTML=controls[phase];
  root.querySelector('[data-cw-talk]').innerHTML=phase===0?'<strong>Talk together, if you like:</strong> Where could drops on the air-facing side come from? Tell someone or point to the part of the picture you mean. You do not need to enter an answer.':'<strong>Talk together, if you like:</strong> Which side has drops, and where was that water just before? What does the tiny drawing show that your eyes could not see?';
  root.querySelector('[data-cw-status]').textContent=announcements[action];
  root.querySelector('#window-frame-title').focus();
 });
}
